test('a degree asked in Catalan or by its vocational acronym is read (NO1-03)', () => {
  const s = compileScreens({ degrees: catalogue('degrees.json'), languages: catalogue('languages.json') });
  const read = t => requiredDegrees(t, s).sort();
  assert.deepEqual(read('Requisits: titulació en electricitat o electrònica'), ['electrical', 'electronics-telecom']);
  assert.deepEqual(read('Tècnic superior en mecatrònica industrial'), ['automation-mechatronics', 'industrial']);
  assert.deepEqual(read('Grau en enginyeria mecànica'), ['mechanical']);
  assert.deepEqual(read('CFGM o CFGS de electricidad'), ['electrical']);
  assert.deepEqual(read('FP en electricidad o electrónica'), ['electrical', 'electronics-telecom']);
  assert.deepEqual(read('Es valorarà formació en electricitat'), []);
});

test('the trade titles the job-portals note left as a question are ours (NO1-08)', () => {
  const titles = [
    ["Chef d'équipe Réseaux électriques", 'fr'],
    ['Facharbeiter Mechatronik, oder Elektrik', 'de'],
    ['Facharbeiter:in Kälteanlagentechnik', 'de'],
    ['KFZ-Facharbeiterin – Buswerkstatt', 'de'],
    ['Chefmonteur HVAC', 'de'],
    ['Hoofdmonteur Installatietechniek', 'nl'],
    ['Technicus PLC/SCADA', 'nl'],
    ['Technicus Hoogspanning', 'nl'],
    ['Assembler Technician', 'gb'],
  ];
  assert.deepEqual(
    titles.filter(([t, cc]) => !titleIsOurs(t, cc)),
    [],
  );
});

